#include <stdlib.h>
#include <string.h>

// Assuming the Image structure is defined as:
// typedef struct {
//     size_t width;
//     size_t height;
//     size_t channels;
//     unsigned char *data;
// } Image;

// Function to allocate and initialize pixel channel arrays
PixelChannels **allocate_pixel_channels(const Image *images) {
    // Determine the maximum number of threads (example value, can be adjusted)
    size_t max_threads = 4; // Placeholder, can be dynamically determined

    // Allocate memory for the array of pixel channel pointers
    PixelChannels **pixel_channels = (PixelChannels **)malloc(max_threads * sizeof(PixelChannels *));
    if (!pixel_channels) {
        return NULL; // Allocation failed
    }

    // Determine the number of columns to use for the pixel channel arrays
    size_t num_columns = images->width;

    // Allocate memory for each pixel channel array
    for (size_t i = 0; i < max_threads; ++i) {
        pixel_channels[i] = (PixelChannels *)calloc(num_columns * images->height * images->channels, sizeof(unsigned char));
        if (!pixel_channels[i]) {
            // Clean up previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(pixel_channels[j]);
            }
            free(pixel_channels);
            return NULL; // Allocation failed
        }
    }

    return pixel_channels;
}
